8	 * "disposable-adjacent" heuristic, kept in one place so the create-time validation
9	 * and the owner risk flag agree on the same list.
10	 *
11	 * <p>A domain is <em>disposable</em> when it is exactly one of the blocklisted
12	 * throw-away email providers ({@code mailinator.com}, {@code tempmail.com},
13	 * {@code guerrillamail.com}); the create endpoint rejects such an email outright.
14	 *
15	 * <p>A domain is <em>disposable-adjacent</em> when it is not itself blocklisted but
16	 * shares a blocklisted provider's registrable label — its second-level label (the
17	 * label immediately before the final TLD label) equals that of a blocklisted
18	 * domain. This catches the same provider under a different TLD
19	 * ({@code mailinator.net}) and subdomains of a blocklisted provider
20	 * ({@code signup.mailinator.com}), which pass create-time validation but are still
21	 * worth flagging as risky. All comparisons are case-insensitive.
22	 */
23	public final class DisposableDomains {
24	
25	    /**
26	     * The exact disposable email domains that are rejected at create time.
27	     */
28	    private static final Set<String> DISPOSABLE_DOMAINS =
29	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
30	
31	    /**
32	     * The second-level labels of the blocklisted domains (e.g. {@code mailinator}),
33	     * used for the disposable-adjacent heuristic.
34	     */
35	    private static final Set<String> DISPOSABLE_LABELS = DISPOSABLE_DOMAINS.stream()
36	        .map(DisposableDomains::secondLevelLabel)
37	        .collect(Collectors.toUnmodifiableSet());
38	
39	    private DisposableDomains() {
40	    }
41	
42	    /**
43	     * Whether {@code domain} is exactly one of the blocklisted disposable domains.
44	     * A {@code null} or blank domain is not disposable.
45	     */
46	    public static boolean isDisposable(String domain) {
47	        if (domain == null || domain.isBlank()) {
48	            return false;
49	        }
50	        return DISPOSABLE_DOMAINS.contains(domain.toLowerCase());
51	    }
52	
53	    /**
54	     * Whether {@code domain} is disposable-adjacent: not itself blocklisted, but sharing
55	     * a blocklisted provider's second-level label (a different TLD or a subdomain of a
56	     * blocklisted provider). A {@code null} or blank domain is not adjacent.
57	     */
58	    public static boolean isDisposableAdjacent(String domain) {
59	        if (domain == null || domain.isBlank()) {
60	            return false;
61	        }
62	        String normalized = domain.toLowerCase();
63	        if (DISPOSABLE_DOMAINS.contains(normalized)) {
64	            return false;
65	        }
66	        return DISPOSABLE_LABELS.contains(secondLevelLabel(normalized));
67	    }
