22	/**
23	 * Maps Owner & OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public interface OwnerMapper {
27	
28	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
29	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
30	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
31	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
32	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
33	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
34	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
35	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
36	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
37	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
38	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
39	    @Mapping(target = "capacityWarning", expression = "java(formatCapacityWarning(owner))")
40	    @Mapping(target = "possibleDuplicate", expression = "java(formatPossibleDuplicate(owner))")
41	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
42	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
43	    @Mapping(target = "ownerSegment", expression = "java(formatOwnerSegment(owner))")
44	    @Mapping(target = "riskFlag", expression = "java(formatRiskFlag(owner))")
45	    OwnerDto toOwnerDto(Owner owner);
46	
47	    /**
48	     * Derive an owner's risk flag, {@code true} when the owner warrants review because any of
49	     * these hold: the owner is a possible duplicate (see {@link #formatPossibleDuplicate(Owner)}),
50	     * its email domain is disposable-adjacent (see
51	     * {@link DisposableDomains#isDisposableAdjacent(String)}), or its city is over its soft
52	     * capacity (its capacity warning is set, see {@link #formatCapacityWarning(Owner)}); otherwise
53	     * {@code false}. Returns {@code null} only when the owner is {@code null}.
54	     */
55	    default Boolean formatRiskFlag(Owner owner) {
56	        if (owner == null) {
57	            return null;
58	        }
59	        return formatPossibleDuplicate(owner)
60	            || formatCapacityWarning(owner)
61	            || isDisposableAdjacentEmail(owner);
62	    }
63	
64	    /**
65	     * Whether an owner's email address sits on a disposable-adjacent domain (see
66	     * {@link DisposableDomains#isDisposableAdjacent(String)}). An absent email, or one without a
67	     * domain part, is not disposable-adjacent.
68	     */
69	    private boolean isDisposableAdjacentEmail(Owner owner) {
70	        String email = owner.getEmail();
71	        if (email == null) {
72	            return false;
73	        }
74	        int at = email.lastIndexOf('@');
75	        if (at < 0 || at == email.length() - 1) {
76	            return false;
77	        }
78	        return DisposableDomains.isDisposableAdjacent(email.substring(at + 1));
79	    }
80	
81	    /**
82	     * Derive an owner's marketing segment, formatted {@code "<TIER>_<AREA>"}. The tier is
83	     * {@code "PREMIUM"} when the owner's {@code membershipLevel} (see
84	     * {@link #formatMembershipLevel(Owner)}) is {@code 3} or more, otherwise {@code "STANDARD"}.
85	     * The area is {@code "METRO"} when the owner's locality (see {@link #formatLocality(Owner)}) is
86	     * a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}. Returns one of
87	     * {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or
88	     * {@code "STANDARD_REGIONAL"}; {@code null} only when the owner is {@code null}.
89	     */
90	    default String formatOwnerSegment(Owner owner) {
91	        if (owner == null) {
92	            return null;
93	        }
94	        Integer level = formatMembershipLevel(owner);
95	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
96	        String area = Regions.isKnownRegion(formatLocality(owner)) ? "METRO" : "REGIONAL";
97	        return tier + "_" + area;
98	    }
99	
100	    /**
101	     * Resolve an owner's possible-duplicate flag, coalescing a {@code null} stored value
102	     * (e.g. for owners created before the flag existed) to {@code false} so the response
103	     * always carries an explicit boolean.
104	     */
105	    default Boolean formatPossibleDuplicate(Owner owner) {
106	        if (owner == null) {
107	            return null;
108	        }
109	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
110	    }
111	
112	    /**
113	     * Derive an owner's age band from its {@code birthDate}, measured as the owner's age in whole
114	     * years on its {@code registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18
115	     * through 64, and {@code "SENIOR"} at 65 and over. Returns {@code null} when the owner, its
116	     * birth date or its registration date is absent, since the band cannot be derived without both
117	     * dates.
118	     */
119	    default String formatAgeBand(Owner owner) {
120	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
121	            return null;
122	        }
123	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
124	        if (age < 18) {
125	            return "MINOR";
126	        }
127	        if (age < 65) {
128	            return "ADULT";
129	        }
130	        return "SENIOR";
131	    }
132	
133	    /**
134	     * Derive an owner's preferred contact channel from its stored contact details:
135	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
136	     */
137	    default String formatContactPreference(Owner owner) {
138	        if (owner == null) {
139	            return null;
140	        }
141	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
142	        return hasEmail ? "EMAIL" : "PHONE";
143	    }
144	
145	    /**
146	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
147	     * (e.g. for owners created before the flag existed) to {@code false} so the response
148	     * always carries an explicit boolean.
149	     */
150	    default Boolean formatBulkSignupWarning(Owner owner) {
151	        if (owner == null) {
152	            return null;
153	        }
154	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
155	    }
156	
157	    /**
158	     * Resolve an owner's capacity-warning flag, coalescing a {@code null} stored value
159	     * (e.g. for owners created before the flag existed) to {@code false} so the response
160	     * always carries an explicit boolean.
161	     */
162	    default Boolean formatCapacityWarning(Owner owner) {
163	        if (owner == null) {
164	            return null;
165	        }
166	        return Boolean.TRUE.equals(owner.getCapacityWarning());
167	    }
168	
169	    /**
170	     * Derive an owner's locality from its {@code memberId}: the leading {@code <REGION>} segment
171	     * (the run of letters before the 2-digit fiscal year), which is the region code derived from
172	     * the owner's postcode. For an owner that has not yet been assigned a member id, the region is
173	     * derived directly from the postcode (see {@link Regions#forPostcode}), yielding the same value
174	     * the id would carry. Returns {@code null} only when the owner itself is {@code null}.
175	     */
176	    default String formatLocality(Owner owner) {
177	        if (owner == null) {
178	            return null;
179	        }
180	        String region = memberIdRegion(owner.getMemberId());
181	        if (region != null) {
182	            return region;
183	        }
184	        return Regions.forPostcode(owner.getPostcode());
185	    }
186	
187	    /**
188	     * The leading {@code <REGION>} segment of a {@code memberId}: its maximal prefix of letters,
189	     * which precedes the 2-digit fiscal year. Returns {@code null} when the member id is
190	     * {@code null} (so callers can fall back to deriving the region from the postcode).
191	     *
192	     * <p>Declared {@code private} so MapStruct does not pick it up as an automatic {@code String ->
193	     * String} conversion and apply it to every string property.
194	     */
195	    private String memberIdRegion(String memberId) {
196	        if (memberId == null) {
197	            return null;
198	        }
199	        int i = 0;
200	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
201	            i++;
202	        }
203	        return memberId.substring(0, i);
204	    }
205	
206	    /**
207	     * Derive an owner's timezone as the IANA name mapped from its locality/region via a fixed
208	     * region-to-timezone table (see {@link Regions#timezoneForRegion}): NSW -> Australia/Sydney,
209	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane. Returns {@code null} when the owner
210	     * is {@code null} or its region is not in the table.
211	     */
212	    default String formatTimezone(Owner owner) {
213	        if (owner == null) {
214	            return null;
215	        }
216	        return Regions.timezoneForRegion(formatLocality(owner));
217	    }
218	
219	    /**
220	     * Compute an owner's membership points. Points start at {@code 0} and gain: {@code 2} when an
221	     * email address is present; {@code 1} when the owner has no namesakes (its
222	     * {@code namesakeCount} is {@code 0}); {@code 2} for a household of three or more members (the
223	     * owner plus its pets); and {@code 3} when the owner's tenure (the number of fiscal years
224	     * elapsed since its {@code registrationDate}'s fiscal year) exceeds {@code 1}. A null or absent
225	     * namesake count is treated as not being zero, so it contributes nothing.
226	     */
227	    default Integer formatMembershipPoints(Owner owner) {
228	        if (owner == null) {
229	            return null;
230	        }
231	        int points = 0;
232	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
233	        if (hasEmail) {
234	            points += 2;
235	        }
236	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
237	        if (uniqueName) {
238	            points += 1;
239	        }
240	        int householdSize = 1 + (owner.getPets() == null ? 0 : owner.getPets().size());
241	        if (householdSize >= 3) {
242	            points += 2;
243	        }
244	        LocalDate registrationDate = owner.getRegistrationDate();
245	        if (registrationDate != null
246	            && BusinessDays.fiscalYearEndYear(LocalDate.now())
247	                - BusinessDays.fiscalYearEndYear(registrationDate) > 1) {
248	            points += 3;
249	        }
250	        return points;
251	    }
252	
253	    /**
254	     * Determine an owner's membership level, a number from {@code 1} to {@code 4} derived from its
255	     * membership points (see {@link #formatMembershipPoints(Owner)}): level {@code 1} for
256	     * {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}
257	     * and {@code 4} for {@code 6} or more.
258	     *
259	     * <p>The level is then capped by the owner's {@code membershipLevelCap} when one is present (see
260	     * {@link Owner#getMembershipLevelCap()}): a new owner's level may not exceed one above the
261	     * current maximum level among its existing household members, so the returned value is the
262	     * smaller of the points-derived level and the cap. A {@code null} cap means no household ceiling
263	     * applies and the points-derived level is returned unchanged.
264	     */
265	    default Integer formatMembershipLevel(Owner owner) {
266	        if (owner == null) {
267	            return null;
268	        }
269	        int points = formatMembershipPoints(owner);
270	        int level;
271	        if (points <= 1) {
272	            level = 1;
273	        }
274	        else if (points <= 3) {
275	            level = 2;
276	        }
277	        else if (points <= 5) {
278	            level = 3;
279	        }
280	        else {
281	            level = 4;
282	        }
283	        Integer cap = owner.getMembershipLevelCap();
284	        if (cap != null && cap < level) {
285	            return cap;
286	        }
287	        return level;
288	    }
289	
290	    /**
291	     * Format an owner's fiscal year as {@code "FY<YY>"}, where {@code YY} is the 2-digit fiscal
292	     * year. The value is read from the {@code <FY>} segment of the owner's {@code memberId} (the
293	     * two digits immediately after the leading region segment), which is the fiscal year the
294	     * owner's (business-day-adjusted) {@code registrationDate} falls in. The fiscal year starts on
295	     * 1 July and is named by the calendar year in which it ends, so a registration date of
296	     * {@code 2026-07-01} is {@code "FY27"} while {@code 2026-06-30} is {@code "FY26"}. For an owner
297	     * with no member id yet, it falls back to deriving the fiscal year directly from the
298	     * registration date. Returns {@code null} when the owner, or both its member id and
299	     * registration date, are absent.
300	     */
301	    default String formatFiscalYear(Owner owner) {
302	        if (owner == null) {
303	            return null;
304	        }
305	        String memberId = owner.getMemberId();
306	        if (memberId != null) {
307	            int start = memberIdRegion(memberId).length();
308	            if (start + 2 <= memberId.length()) {
309	                return "FY" + memberId.substring(start, start + 2);
310	            }
311	        }
312	        if (owner.getRegistrationDate() == null) {
313	            return null;
314	        }
315	        return String.format("FY%02d", BusinessDays.fiscalYearEndYear(owner.getRegistrationDate()) % 100);
316	    }
317	
318	    /**
319	     * Format an owner's stored E.164 telephone for humans as the country code, a space, then the
320	     * national digits grouped in threes, e.g. {@code "+61412345678"} becomes
321	     * {@code "+61 412 345 678"} (see {@link E164Telephone#toDisplay}). The raw {@code telephone}
322	     * is left in E.164 form. Returns {@code null} when the owner or its telephone is absent.
323	     */
324	    default String formatTelephoneDisplay(Owner owner) {
325	        if (owner == null) {
326	            return null;
327	        }
328	        return E164Telephone.toDisplay(owner.getTelephone());
329	    }
330	
331	    /**
332	     * Compose an owner's salutation as its {@code title} followed by a single space and the
333	     * last name (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the
334	     * salutation is just the last name. Returns {@code null} when the owner is {@code null}.
335	     */
336	    default String formatSalutation(Owner owner) {
337	        if (owner == null) {
338	            return null;
339	        }
340	        String title = owner.getTitle();
341	        if (title == null || title.trim().isEmpty()) {
342	            return owner.getLastName();
343	        }
344	        return title + " " + owner.getLastName();
345	    }
346	
347	    /**
348	     * Build a link to an owner's own resource, formed as {@code "/api/owners/"} followed by the
349	     * owner's id. Returns {@code null} when the owner or its id is absent, since the link cannot
350	     * be formed without an id.
351	     */
352	    default String formatSelfLink(Owner owner) {
353	        if (owner == null || owner.getId() == null) {
354	            return null;
355	        }
356	        return "/api/owners/" + owner.getId();
357	    }
